// === Tab: main ===
let meatballShader;

const N_balls = 8,
			meatballs = [];

let mball;

function preload(){
	mball = loadImage("data:image/png;base64,");

	meatballShader = getShader(this._renderer);
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);

	for (let i = 0; i < N_balls; i ++) meatballs.push(new Meatball());
}

function draw() {
	var data = [];

	for (const ball of meatballs) {
		ball.update();
		data.push(ball.pos.x, ball.pos.y, ball.radius);
	}
	shader(meatballShader);

	meatballShader.setUniform("meatballs", data);
	meatballShader.setUniform("meatballTex", mball);
	rect(0, 0, width, height);
}

// OpenProcessing has a bug where it always creates a scrollbar on Chromium.
function mouseWheel() { // This stops the canvas from scrolling by a few pixels.
	return false;
}

// === Tab: meatball ===
class Meatball {
	constructor() {
		const size = Math.random();
		this.vel = p5.Vector.random2D().mult(4 * (1 - size) + 2);
		this.radius = 100 * size + 20;

		this.pos = new p5.Vector(random(this.radius, width - this.radius), random(this.radius, height - this.radius));
	}

	update() {
		this.pos.add(this.vel);

		if (this.pos.x < this.radius || this.pos.x > width  - this.radius) this.vel.x *= -1;
		if (this.pos.y < this.radius || this.pos.y > height - this.radius) this.vel.y *= -1;
	}
}

// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 meatballs[${N_balls}];
		uniform sampler2D meatballTex;

		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;

		const float MEATWIDTH = ${mball.width}.0;
		const float MEATHEIGHT = ${mball.height}.0;

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;

			vec3 closestBall;
			float closestDist = WIDTH * WIDTH + HEIGHT * HEIGHT;
			for (int i = 0; i < ${N_balls}; i++) {
				vec3 ball = meatballs[i];
				float dx = ball.x - x;
				float dy = ball.y - y;
				if(dx * dx + dy * dy < closestDist){
					closestDist = dx * dx + dy * dy;
					closestBall = ball;
				}
				float r = ball.z;
				v += r * r / (dx * dx + dy * dy);
			}

			vec2 uv = vTexCoord;
			uv.x = (uv.x - closestBall.x / WIDTH) / 1.3 + MEATWIDTH / 2.0;
			uv.y = (uv.y - closestBall.y / HEIGHT) / 1.3 + MEATHEIGHT / 2.0;
			vec4 meat = texture2D(meatballTex, uv);

			if (v > 1.0) gl_FragColor = meat;
			else gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
		}
	`;

	return createShader(vert, frag);
}

